package Program.api;
import java.net.URI; import java.net.http.*; import java.time.Duration; import java.util.*;
/** Minimal OpenAI-compatible Groq client: transport only, no financial business rules. */
public class GroqClient {private static final String ENDPOINT="https://api.groq.com/openai/v1/chat/completions";
 public String chat(String system,String user) throws Exception {String key=System.getenv("GROQ_API_KEY");if(key==null||key.isBlank())throw new IllegalStateException("GROQ_API_KEY is not configured.");String body="{\"model\":\"openai/gpt-oss-20b\",\"temperature\":0.35,\"messages\":[{\"role\":\"system\",\"content\":\""+escape(system)+"\"},{\"role\":\"user\",\"content\":\""+escape(user)+"\"}]}";HttpRequest request=HttpRequest.newBuilder(URI.create(ENDPOINT)).timeout(Duration.ofSeconds(35)).header("Content-Type","application/json").header("Authorization","Bearer "+key).POST(HttpRequest.BodyPublishers.ofString(body)).build();HttpResponse<String> response=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(15)).build().send(request,HttpResponse.BodyHandlers.ofString());if(response.statusCode()/100!=2)throw new IllegalStateException("AI service returned status "+response.statusCode());return content(response.body());}
 private String escape(String s){return s.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\r","");} private String content(String json){int p=json.indexOf("\"content\"");if(p<0)throw new IllegalStateException("Malformed AI response.");int colon=json.indexOf(':',p);int start=json.indexOf('"',colon+1);StringBuilder out=new StringBuilder();for(int i=start+1;i<json.length();i++){char c=json.charAt(i);if(c=='\\'&&i+1<json.length()){char n=json.charAt(++i);out.append(n=='n'?'\n':n=='t'?'\t':n);continue;}if(c=='"')return out.toString();out.append(c);}throw new IllegalStateException("Malformed AI response.");}}
